// Verify the HMAC signature from the admin, then expand the batch into one
// item per contact.
//
// Uses the Web Crypto API (globalThis.crypto), which is a standard global in
// Node 18+. The Code node sandbox blocks require('crypto') unless n8n is
// started with NODE_FUNCTION_ALLOW_BUILTIN=crypto, so avoid the module.
//
// The signature covers the exact bytes the admin sent, so the raw body is used
// here — re-serializing parsed JSON produces different bytes and never matches.
// The Webhook node must have "Raw Body" enabled.

const cfg = $('Config').first().json;
const secret = (cfg.webhookSecret || '').trim();

// Read the Webhook node directly rather than $input: the Config node is a Set
// node, which replaces the item with just its own fields, so the body and
// headers are not on the incoming item by the time this runs.
const item = $('Webhook').first();

// Raw Body arrives as base64 binary; fall back to the parsed body if the
// option is off (unsigned mode only — the bytes will not match a signature).
let raw;
if (item.binary && item.binary.data && item.binary.data.data) {
  const b64 = item.binary.data.data;
  raw = typeof Buffer !== 'undefined'
    ? Buffer.from(b64, 'base64').toString('utf8')
    : new TextDecoder().decode(Uint8Array.from(atob(b64), (c) => c.charCodeAt(0)));
} else {
  raw = JSON.stringify(item.json.body ?? item.json);
}

if (secret) {
  const header = (item.json.headers || {})['x-vermo-signature'] || '';
  const sent = String(header).replace(/^sha256=/, '').toLowerCase();

  const subtle = globalThis.crypto && globalThis.crypto.subtle;
  if (!subtle) {
    throw new Error('Web Crypto is unavailable in this n8n runtime. Either upgrade to Node 18+, or clear webhookSecret in the Config node to disable signature checking.');
  }

  const enc = new TextEncoder();
  const key = await subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const sigBuf = await subtle.sign('HMAC', key, enc.encode(raw));
  const expected = Array.from(new Uint8Array(sigBuf))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');

  // Constant-time compare — a plain === leaks how much of the prefix matched.
  let diff = sent.length ^ expected.length;
  for (let i = 0; i < sent.length && i < expected.length; i++) {
    diff |= sent.charCodeAt(i) ^ expected.charCodeAt(i);
  }
  if (diff !== 0) {
    throw new Error('Invalid signature — the payload did not come from the admin dashboard, or the shared secret does not match.');
  }
}

let payload;
try {
  payload = JSON.parse(raw);
} catch (e) {
  throw new Error('Body is not valid JSON: ' + e.message);
}

const contacts = Array.isArray(payload.contacts) ? payload.contacts : [];
if (!contacts.length) {
  return [{ json: { __empty: true, batch: payload.batch || null } }];
}

// One output item per contact, carrying the batch info along for the summary.
return contacts.map((c) => ({
  json: {
    ...c,
    __batch: payload.batch || null,
    __test: !!(payload.batch && payload.batch.test),
  },
}));

// Build the Twenty search filter for each contact.
//
// Runs over all items so contacts that cannot be matched are dropped here
// rather than reaching the HTTP node with an empty filter. Email is the key
// when present; phone is the fallback.
const out = [];
let skipped = 0;
let total = 0;

for (const item of $input.all()) {
  const c = item.json;
  if (c.__empty) continue;                 // empty batch marker
  total++;

  const email = (c.email || '').trim();
  const phone = (c.phoneNumber || '').trim();

  let filter = '';
  if (email) filter = `emails.primaryEmail[eq]:${email}`;
  else if (phone) filter = `phones.primaryPhoneNumber[eq]:${phone}`;

  // Nothing for the CRM to key on — skip instead of creating an orphan record.
  if (!filter) { skipped++; continue; }

  out.push({ json: { ...c, __filter: filter } });
}

// Never return an empty list: with no items every downstream node is skipped,
// including Respond to Webhook, and the caller would hang until it times out.
// This marker item is routed straight to the response by the IF node.
if (!out.length) {
  return [{ json: { __nothing: true, received: total, skipped } }];
}

return out;

// Merge each Twenty lookup result with its contact and build the request body.
// Emits __action so the IF node can route create vs update.
//
// The HTTP node returns one response per input item in order, so responses are
// matched to contacts by index.
const cfg = $('Config').first().json;
const segmentField = (cfg.segmentField || '').trim();
const segmentMode = (cfg.segmentMode || 'text').toLowerCase();

const contacts = $('Build search filter').all();
const responses = $input.all();
const out = [];

for (let i = 0; i < responses.length; i++) {
  const contact = contacts[i] && contacts[i].json;
  if (!contact) continue;

  // Full Response is on, so the payload is { statusCode, body, headers }.
  const raw = responses[i].json || {};
  const status = raw.statusCode != null ? raw.statusCode : 200;
  const payload = raw.body != null ? raw.body : raw;

  // A failed lookup must not fall through to "not found" — that would create a
  // duplicate for someone who already exists. Every contact hits the same URL
  // and credential, so one failure means the whole batch is misconfigured.
  if (status >= 400) {
    // Twenty puts the useful detail in `messages`; `error` is only a code.
    const msg = (payload && Array.isArray(payload.messages) && payload.messages.length)
      ? payload.messages.join('; ')
      : (payload && (payload.message || payload.error))
        || (typeof payload === 'string' ? payload : JSON.stringify(payload || {}).slice(0, 200));
    const hint = (status === 401 || status === 403)
      ? 'Set twentyApiKey in the Config node (Twenty > Settings > API & Webhooks > Create API key).'
      : status === 429
        ? 'Twenty rate limit hit. Each contact costs two calls (lookup + write), so lower Batch size on the CRM Sync page.'
        : status === 404
          ? 'Check twentyUrl in the Config node.'
          : 'Check the Twenty instance is reachable and healthy.';
    throw new Error(`Twenty lookup failed (HTTP ${status}): ${msg}. ${hint}`);
  }

  const people = (payload && payload.data && payload.data.people) || [];
  const found = people.length ? people[0] : null;

  const body = {
    name: { firstName: contact.firstName || '', lastName: contact.lastName || '' },
  };

  if (contact.email) {
    body.emails = { primaryEmail: contact.email };
  }
  if (contact.phoneNumber) {
    body.phones = {
      primaryPhoneNumber: contact.phoneNumber,
      primaryPhoneCallingCode: contact.phoneCallingCode || '',
    };
  }

  // Segments go into a custom field on Person. A Text field takes a joined
  // string; a Multi-Select field takes the array of slugs.
  const segments = Array.isArray(contact.segments) ? contact.segments : [];
  if (segmentField) {
    body[segmentField] = segmentMode === 'multiselect' ? segments : segments.join(', ');
  }

  out.push({
    json: {
      __action: found ? 'update' : 'create',
      __personId: found ? found.id : null,
      __userId: contact.userId,
      __segments: segments,
      body,
    },
  });
}

return out;

// Collapse the per-contact results into one response for the admin.
//
// Full Response is on, so a rejected write is visible here as a status code
// instead of silently looking like "no person returned".
const items = $input.all();

// The "nothing to do" path routes the marker item here directly.
const marker = items.find((i) => i.json && i.json.__nothing);
if (marker) {
  return [{
    json: {
      ok: true,
      received: marker.json.received || 0,
      upserted: 0,
      failed: 0,
      skipped: marker.json.skipped || 0,
      note: (marker.json.received || 0) === 0
        ? 'The request reached the workflow but carried no contacts.'
        : `All ${marker.json.skipped || 0} contact(s) in this batch lacked an email or phone to match on.`,
    },
  }];
}

let upserted = 0;
const errors = [];

for (const item of items) {
  const raw = item.json || {};
  const status = raw.statusCode != null ? raw.statusCode : 200;
  const payload = raw.body != null ? raw.body : raw;
  const person = (payload && payload.data && (payload.data.createPerson || payload.data.updatePerson)) || null;

  if (status < 400 && person) {
    upserted++;
  } else {
    // Twenty puts the useful detail in `messages`; `error` is only a code.
    const msg = (payload && Array.isArray(payload.messages) && payload.messages.length)
      ? payload.messages.join('; ')
      : (payload && (payload.message || payload.error))
        || (typeof payload === 'string' ? payload : JSON.stringify(payload || {}).slice(0, 300));
    errors.push(`HTTP ${status}: ${Array.isArray(msg) ? msg.join('; ') : msg}`);
  }
}

// ok:false makes the admin show the failure instead of reporting delivery.
return [{
  json: {
    ok: errors.length === 0,
    received: items.length,
    upserted,
    failed: errors.length,
    errors: errors.slice(0, 5),
  },
}];
